#[test]
fn tck_0100_temporal_arithmetic() {
    let mut failures = Vec::new();
    for &(id, lhs, op, rhs, expected) in CASES {
        let (a, b) = (at(lhs), at(rhs));
        assert_ne!(a, V::Null, "{id}: lhs {lhs:?} must parse");
        assert_ne!(b, V::Null, "{id}: rhs {rhs:?} must parse");
        let r = if op == '+' { add(&a, &b) } else { sub(&a, &b) };
        if !matches_expected(&r, expected) {
            failures.push(format!(
                "{id}: {lhs} {op} {rhs} = {} (expected {expected})",
                show(&r)
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(CASES.len() >= 200);
}
